target.css:
:root {
  --ink: #20303b;
  --muted: #60717a;
  --paper: #fffdf7;
  --line: #d8e1df;
  --sky: #dff3f5;
  --teal: #197b82;
  --sun: #f5bd48;
  --coral: #e96c54;
}

* {
  box-sizing: border-box;
}

.wind-card {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -.03em;
}

.status {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--sky);
  color: var(--teal);
  font-size: 12px;
  font-weight: 700;
}

.conditions {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 16px;
  padding: 16px 18px;
}

.wind-reading {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px;
  border-radius: 12px;
  background: var(--sky);
}

.compass {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 50%;
  background: var(--teal);
  color: var(--paper);
  font-size: 22px;
  line-height: 1;
}

.wind-reading strong,
.wind-reading span:not(.compass) {
  display: block;
}

.wind-reading strong {
  font-size: 18px;
  line-height: 1.1;
}

.wind-reading span:not(.compass) {
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 0;
}

.details section {
  padding: 9px 7px;
  border: 1px solid var(--line);
  border-radius: 10px;
  text-align: center;
}

dt {
  color: var(--muted);
  font-size: 11px;
}

dd {
  margin: 3px 0 0;
  font-size: 13px;
  font-weight: 700;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--sun);
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 12px;
  background: var(--coral);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

